function decodeBase64(input: string): Uint8Array {
  const text = atob(input);
  const out = new Uint8Array(text.length);
  for (let i = 0; i < text.length; i++) out[i] = text.charCodeAt(i);
  return out;
}

const RELIEF = decodeBase64(RELIEF_BASE64);

function wrapLon(lon: number): number {
  return ((lon % 360) + 360) % 360;
}

function clampLat(lat: number): number {
  return Math.max(-90, Math.min(90, lat));
}

function grayAt(x: number, y: number): number {
  const ix = ((x % WIDTH) + WIDTH) % WIDTH;
  const iy = Math.max(0, Math.min(HEIGHT - 1, y));
  return RELIEF[iy * WIDTH + ix] / 255;
}

/** Bilinear sample of the global MOLA relief prior in kilometres. */
export function marsMolaElevationKm(lat: number, lon: number): number {
  const fx = (wrapLon(lon) / 360) * WIDTH;
  const fy = ((90 - clampLat(lat)) / 180) * (HEIGHT - 1);
  const x0 = Math.floor(fx);
  const y0 = Math.floor(fy);
  const tx = fx - x0;
  const ty = fy - y0;
  const a = grayAt(x0, y0);
  const b = grayAt(x0 + 1, y0);
  const c = grayAt(x0, y0 + 1);
  const d = grayAt(x0 + 1, y0 + 1);
  const v = a * (1 - tx) * (1 - ty) + b * tx * (1 - ty) + c * (1 - tx) * ty + d * tx * ty;
  return MIN_KM + v * RANGE_KM;
}

/**
 * Difference from the global prior at a site, useful for local relief without
 * reintroducing the planet-wide datum into the playable height field.
 */
export function marsMolaRelativeKm(lat: number, lon: number, datumKm: number): number {
  return marsMolaElevationKm(lat, lon) - datumKm;
}
